// Wet ground + rain adapter for The Walking Trade map. The wet ground shader (puddles, soak band, damp halo, rain
// rings, painted marks with chipped edges), the planar mirror and the rain streaks / splashes / eave drips come from
// the Saltline port (js/sl/ground-sl.js, generated by tools/port-sl-ground.js from Felix Rieseberg's Saltline). This
// file lays the apron over the car park, yard, back lot, sidewalks and street, hands the module this game's camera,
// quality, buildings and rain level (G.ctx.fx), and answers puddle queries.
import * as THREE from '../vendor/three.module.min.js';
import { buildMask, buildDetail, dataTexture, buildMarks, buildApron, buildPlanar, buildRain, sampleMask, MASK_RECT } from './sl/ground-sl.js';
import { SUN_DIR, SUN_COLOR, PALETTE } from './sky.js';
import { noMask, keepAlpha } from './mats.js';

// ground rectangles [x0, z0, x1, z1, y]: the top faces of the rules layer's lot / yard / street blocks (js/sim/world.js
// build_exterior). Their old triangles are dropped by the scene-graph filter (see APRON_RECTS users in plug/env.js).
export const APRON_RECTS = [
  [-23.4, -20.5, 31.1, 5.25, -0.02],   // back lot (concrete) round the buildings
  [-23.4, 5.25, 31.1, 40.0, 0.0],      // yard (concrete) + car park (asphalt)
  [-90.0, 45.0, 90.0, 46.0, 0.02],     // near sidewalk
  [-90.0, 46.0, 90.0, 54.0, 0.0],      // street
  [-90.0, 54.0, 90.0, 58.0, 0.02],     // far sidewalk
];
// buildings: no rain, no splashes inside (min/max xyz)
const BUILDINGS = [
  [-9.95, -0.2, -5.45, 5.45, 3.55, 5.45],
  [-5.45, -0.2, -19.4, 15.2, 7.0, -5.05],
  [5.05, -0.2, -5.45, 25.2, 3.6, 3.4],
];

function apronGeometry() {
  const pos = [], nrm = [], uv = [], idx = [];
  for (const [x0, z0, x1, z1, y] of APRON_RECTS) {
    const b = pos.length / 3;
    pos.push(x0, y, z0, x1, y, z0, x1, y, z1, x0, y, z1);
    for (let k = 0; k < 4; k++) nrm.push(0, 1, 0);
    uv.push(x0, z0, x1, z0, x1, z1, x0, z1);
    idx.push(b, b + 2, b + 1, b, b + 3, b + 2);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx); g.computeBoundingSphere();
  return g;
}

export function buildGround(G) {
  const r = G.renderer, low = G.quality.name === 'low';
  const aniso = Math.min(8, r.capabilities.getMaxAnisotropy ? r.capabilities.getMaxAnisotropy() : 1);
  const n = low ? 512 : 1024;
  const mask = buildMask(n);
  const maskTex = dataTexture(mask, n, { repeat: false, aniso: 2 });
  const dn = low ? 256 : 512;
  const { det, nrm } = buildDetail(dn);
  const black = new THREE.DataTexture(new Uint8Array([0, 0, 0, 255]), 1, 1); black.needsUpdate = true;
  const tex = { mask: maskTex, detail: dataTexture(det, dn, { aniso }), detailN: dataTexture(nrm, dn, { aniso }), marks: buildMarks(low ? 1024 : 2048, aniso), black };
  const wetG = { value: 1 };
  const interiorBoxes = BUILDINGS.map((b) => ({ min: new THREE.Vector3(b[0], b[1], b[2]), max: new THREE.Vector3(b[3], b[4], b[5]) }));
  const shim = {
    mats: { uniforms: { wet: wetG } },
    quality: { rain: low ? 0.45 : G.quality.name === 'medium' ? 0.75 : 1, planar: low || G.params.planar === '0' ? 0 : 0.5 },
    rng: { fork: () => { let s = 7331; return () => ((s = (s * 16807) % 2147483647) / 2147483647); } },
    get camera() { return G.camera; },
    renderer: r,
    render: {
      resolution: null,
      renderWorld: (cam, target) => {
        const prev = r.getRenderTarget(), ac = r.autoClear;
        r.setRenderTarget(target); r.setClearColor(0x000000, 1); r.clear(true, true, false);
        r.autoClear = false;
        try { r.render(G.scene, cam); } finally { r.autoClear = ac; r.setRenderTarget(prev); }
      },
    },
    level: { interiorBoxes, skylights: [] },
    events: { emit: (name, d) => { if (name === 'thunder' && api.onThunder) api.onThunder(d.intensity); } },
  };
  const apron = buildApron(shim, tex);
  apron.mesh.geometry.dispose(); apron.mesh.geometry = apronGeometry();
  noMask(apron.material);
  apron.material.customProgramCacheKey = () => 'twt-apron-1';
  const rain = buildRain(shim, tex);
  rain.setRain(0);
  // additive streaks must not write the alpha channel (the SSR pass reads it as a reflectivity mask)
  for (const m of [rain.rain, rain.splash]) { m.layers.set(0); m.material.userData.additive = true; keepAlpha(m.material); }
  const planar = buildPlanar(shim, apron.uniforms, [apron.mesh, rain.rain, rain.splash, G.sg.viewRoot]);
  const root = new THREE.Group(); root.name = 'twt-ground';
  root.add(apron.mesh, rain.rain, rain.splash);
  G.scene.add(root);
  const inInterior = (x, z) => BUILDINGS.some((b) => x > b[0] && x < b[3] && z > b[2] && z < b[5]);
  const inMask = (x, z) => x > MASK_RECT.x0 && x < MASK_RECT.x0 + MASK_RECT.size && z > MASK_RECT.z0 && z < MASK_RECT.z0 + MASK_RECT.size;
  const ru = rain.rain.material.uniforms, su = rain.splash.material.uniforms;
  let t = 0;
  const api = {
    apron, rain, planar, root, onThunder: null,
    puddleDepth(x, z) { return !inMask(x, z) || inInterior(x, z) ? -0.2 : 0.5 - sampleMask(mask, n, x, z, 0); },
    isPuddle(x, z) { return api.puddleDepth(x, z) > 0.015; },
    prePass(renderer, camera) { if (apron.mesh.visible) planar.pass(renderer, G.scene, camera); },
    update(dt) {
      t += dt;
      const fx = G.ctx.fx, wet = Math.max(fx.wet, fx.rain);
      rain.setRain(G.params.rain === '0' ? 0 : fx.rain);
      rain.update(dt);
      apron.uniforms.uTime.value = t;
      apron.uniforms.uRain.value = rain.rainLevel;
      wetG.value = Math.min(1, 0.3 + wet);
      apron.uniforms.uLow.value = (1 - Math.min(1, wet)) * 0.05;
      // the rain streaks are lit by the current sun / moon and the fog colour
      const sunK = G.lights.sun.intensity / 9;
      for (const u of [ru, su]) {
        u.uSunDir.value.copy(SUN_DIR);
        u.uSunCol.value.copy(SUN_COLOR).multiplyScalar(1.9 * sunK);
        u.uAmb.value.copy(PALETTE.fog).multiplyScalar(0.15 * (0.25 + 0.75 * Math.min(1, sunK * 1.5)));
        // at night the streaks still catch the lamps and the shop light
        const a = u.uAmb.value; a.r = Math.max(a.r, 0.05); a.g = Math.max(a.g, 0.048); a.b = Math.max(a.b, 0.045);
      }
    },
  };
  return api;
}
